INSERT INTO `ab_blocks` (`id`, `category_id`, `blockid`, `label`, `media`, `attributes`, `content`, `status`, `seq`, `theme_id`, `created_at`, `updated_at`) VALUES
(80, 4, 'about2', 'About 2', '<svg xmlns=\"http://www.w3.org/2000/svg\" \r\n height=\"50px\">\r\n  <!-- Embedding an image -->\r\n  <image xlink:href=\"https://test.webfire.in/public/admin/theme/img/user.jpg\" width=\"100%\" height=\"100%\" />\r\n</svg>', '{class : \'\',id:\'\'}', '<div class=\"site-wrapper-reveal\">\r\n            <!--===========  feature-large-images-wrapper  Start =============-->\r\n            <div class=\"feature-large-images-wrapper section-space--ptb_100\">\r\n                <div class=\"container\">\r\n\r\n                    <div class=\"row\">\r\n                        <div class=\"col-lg-12\">\r\n                            <!-- section-title-wrap Start -->\r\n                            <div class=\"section-title-wrap text-center section-space--mb_60\">\r\n                                <h6 class=\"section-sub-title mb-20\">Our company</h6>\r\n                                <h3 class=\"heading\">Share the joy of achieving <span class=\"text-color-primary\"> glorious   <br> moments</span> &amp; climbed up <span class=\"text-color-primary\">the top.</span></h3>\r\n                            </div>\r\n                            <!-- section-title-wrap Start -->\r\n                        </div>\r\n                    </div>\r\n\r\n                    <div class=\"cybersecurity-about-box\">\r\n                        <div class=\"row\">\r\n                            <div class=\"col-lg-5 offset-lg-1\">\r\n                                <div class=\"modern-number-01 number-two\">\r\n                                    <h2 class=\"heading  me-5\"><span class=\"mark-text\">38</span>Years’ Experience in IT</h2>\r\n                                    <h5 class=\"heading mt-30\">We’ve been triumphing all these <span class=\"text-color-primary\"> 38 years. </span> Sacrifices are made up with success. </h5>\r\n                                </div>\r\n                            </div>\r\n\r\n                            <div class=\"col-lg-5 ms-auto\">\r\n                                <div class=\"faq-wrapper\">\r\n                                    <div id=\"accordion\">\r\n                                        <div class=\"card\">\r\n                                            <div class=\"card-header\" id=\"headingOne\">\r\n                                                <h5 class=\"mb-0\">\r\n                                                    <button class=\"btn-link\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseOne\" aria-expanded=\"true\" aria-controls=\"collapseOne\">\r\n                                                        How can we help your business? <span> <i class=\"fas fa-chevron-down\"></i>\r\n                                        <i class=\"fas fa-chevron-up\"></i> </span>\r\n                                                    </button>\r\n                                                </h5>\r\n                                            </div>\r\n\r\n                                            <div id=\"collapseOne\" class=\"collapse show\" aria-labelledby=\"headingOne\" data-bs-parent=\"#accordion\">\r\n                                                <div class=\"card-body\">\r\n                                                    <p>Through the collaboration with customers in discussing needs and demand, we\'re able to attain mutual understanding, gain customer trust to offer appropriate advice, and bring about suggestions on suitable technology to transform your business. </p>\r\n                                                </div>\r\n                                            </div>\r\n                                        </div>\r\n                                        <div class=\"card\">\r\n                                            <div class=\"card-header\" id=\"headingTwo\">\r\n                                                <h5 class=\"mb-0\">\r\n                                                    <button class=\"btn-link collapsed\" data-bs-togg