(193, 338, '* { box-sizing: border-box; } body {margin: 0;}body{background:#D0D8DB;padding-top:60px;padding-bottom:40px;}textarea{resize:none;}.rounded-social-buttons{text-align:center;}.rounded-social-buttons .social-button{display:inline-block;position:relative;cursor:pointer;width:3.125rem;height:3.125rem;border:0.125rem solid transparent;padding:0;text-decoration:none;text-align:center;color:#fefefe;font-size:1.5625rem;font-weight:normal;line-height:2em;border-radius:1.6875rem;transition:all 0.5s ease;margin-right:0.25rem;margin-bottom:0.25rem;}.rounded-social-buttons .social-button:hover, .rounded-social-buttons .social-button:focus{-webkit-transform:rotate(360deg);-ms-transform:rotate(360deg);transform:rotate(360deg);}.fa-facebook-f{font-size:25px;}.fa-linkedin{font-size:25px;}.fa-youtube{font-size:25px;}.fa-instagram, .rounded-social-buttons .fa-twitter{font-size:25px;}.rounded-social-buttons .social-button.facebook{background:#3b5998;}.rounded-social-buttons .social-button.facebook:hover, .rounded-social-buttons .social-button.facebook:focus{color:#3b5998;background:#fefefe;border-color:#3b5998;}.rounded-social-buttons .social-button.twitter{background:#55acee;}.rounded-social-buttons .social-button.twitter:hover, .rounded-social-buttons .social-button.twitter:focus{color:#55acee;background:#fefefe;border-color:#55acee;}.rounded-social-buttons .social-button.linkedin{background:#007bb5;}.rounded-social-buttons .social-button.linkedin:hover, .rounded-social-buttons .social-button.linkedin:focus{color:#007bb5;background:#fefefe;border-color:#007bb5;}.rounded-social-buttons .social-button.youtube{background:#bb0000;}.rounded-social-buttons .social-button.youtube:hover, .rounded-social-buttons .social-button.youtube:focus{color:#bb0000;background:#fefefe;border-color:#bb0000;}.rounded-social-buttons .social-button.instagram{background:#125688;}.rounded-social-buttons .social-button.instagram:hover, .rounded-social-buttons .social-button.instagram:focus{color:#125688;background:#fefefe;border-color:#125688;}', '&lt;body id=&quot;imy2&quot;&gt;&lt;div id=&quot;ik61&quot;&gt;&lt;footer&gt;&lt;div class=&quot;rounded-social-buttons&quot;&gt;&lt;a href=&quot;https://www.facebook.com/&quot; target=&quot;_blank&quot; class=&quot;social-button facebook&quot;&gt;&lt;i class=&quot;fab fa-facebook-f&quot;&gt;&lt;/i&gt;&lt;/a&gt;&lt;a href=&quot;https://www.twitter.com/&quot; target=&quot;_blank&quot; class=&quot;social-button twitter&quot;&gt;&lt;i class=&quot;fab fa-twitter&quot;&gt;&lt;/i&gt;&lt;/a&gt;&lt;a href=&quot;https://www.linkedin.com/&quot; target=&quot;_blank&quot; class=&quot;social-button linkedin&quot;&gt;&lt;i class=&quot;fab fa-linkedin&quot;&gt;&lt;/i&gt;&lt;/a&gt;&lt;a href=&quot;https://www.youtube.com/&quot; target=&quot;_blank&quot; class=&quot;social-button youtube&quot;&gt;&lt;i class=&quot;fab fa-youtube&quot;&gt;&lt;/i&gt;&lt;/a&gt;&lt;a href=&quot;https://www.instagram.com/&quot; target=&quot;_blank&quot; class=&quot;social-button instagram&quot;&gt;&lt;i class=&quot;fab fa-instagram&quot;&gt;&lt;/i&gt;&lt;/a&gt;&lt;/div&gt;&lt;/footer&gt;&lt;/div&gt;', 27, '1', '2024-03-28 14:04:03', '2024-03-28 14:04:03'),
